with c as(insert into campaigns(code,name,total_inventory) values('JLPT_SPIN_2026','Báo điểm JLPT - Nhận quà Edura',50) returning id), p as(insert into prizes(campaign_id,code,name,total_qty,wheel_index,display_order) select c.id,v.* from c cross join(values('SCHOLARSHIP_100','Học bổng 100% JLPT Video',15,0,0),('SCHOLARSHIP_80','Học bổng 80% JLPT Video',5,1,1),('SCHOLARSHIP_50','Học bổng 50% JLPT Video',5,2,2),('VOUCHER_1000K','Voucher 1.000.000đ',2,3,3),('VOUCHER_800K','Voucher 800.000đ',11,4,4),('VOUCHER_500K','Voucher 500.000đ',12,5,5))v(code,name,total_qty,wheel_index,display_order) returning *) insert into prize_units(campaign_id,prize_id,unit_no) select p.campaign_id,p.id,row_number()over() from p cross join lateral generate_series(1,p.total_qty);

set constraints all immediate;
